import{_ as a,o as i,c as l,ae as t}from"./chunks/framework.1Lna8NcP.js";const h=JSON.parse('{"title":"2026-04-12 Plaid Pricing + Alternatives Evaluation","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/plans/2026-04-12-plaid-pricing.md","filePath":"superpowers/plans/2026-04-12-plaid-pricing.md"}'),r={name:"superpowers/plans/2026-04-12-plaid-pricing.md"};function o(n,e,s,d,c,u){return i(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="_2026-04-12-plaid-pricing-alternatives-evaluation" tabindex="-1">2026-04-12 Plaid Pricing + Alternatives Evaluation <a class="header-anchor" href="#_2026-04-12-plaid-pricing-alternatives-evaluation" aria-label="Permalink to &quot;2026-04-12 Plaid Pricing + Alternatives Evaluation&quot;">​</a></h1><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Phase 5 keeps Plaid optional and local-first. Plaid is used for users who want live sync, while CSV/Excel/manual remain complete standalone paths.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ul><li>Use Plaid for optional linked account flows (transactions + liabilities).</li><li>Keep Google Sheets support as CSV-export pull only.</li><li>Do not require any paid provider to use Libertas core features.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives Considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives Considered&quot;">​</a></h2><ol><li>Plaid only</li></ol><ul><li>Rejected as mandatory default due to privacy positioning and vendor dependency.</li></ul><ol start="2"><li>Free-only connector strategy</li></ol><ul><li>Rejected as exclusive default due to weaker institutional coverage and support variability.</li></ul><ol start="3"><li>Current hybrid (chosen)</li></ol><ul><li>CSV/Excel/manual baseline + optional Plaid + optional Sheets feed.</li></ul><h2 id="user-facing-policy" tabindex="-1">User-Facing Policy <a class="header-anchor" href="#user-facing-policy" aria-label="Permalink to &quot;User-Facing Policy&quot;">​</a></h2><ul><li>Integrations appear only in Settings.</li><li>Non-integrated users should never see blocking prompts.</li><li>Secrets are stored locally and encrypted at rest.</li></ul><h2 id="follow-ups" tabindex="-1">Follow-ups <a class="header-anchor" href="#follow-ups" aria-label="Permalink to &quot;Follow-ups&quot;">​</a></h2><ul><li>Add usage telemetry strictly local (counts only) for sync reliability diagnostics.</li><li>Re-evaluate alternatives each major release for cost/coverage shifts.</li></ul>',16)])])}const m=a(r,[["render",o]]);export{h as __pageData,m as default};
